import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int prev = sc.nextInt();
        int run = 1, best = 1;
        for (int i = 1; i < n; i++) {
            int v = sc.nextInt();
            if (v == prev) {
                run++;
            } else {
                run = 1;
            }
            if (run > best) {
                best = run;
            }
            prev = v;
        }
        System.out.println(best);
    }
}

