import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        int best = 1;
        for (int i = 0; i < s.length(); i++) {
            for (int j = i; j < s.length(); j++) {
                boolean pal = true;
                for (int k = 0; k < (j - i + 1) / 2; k++) {
                    if (s.charAt(i + k) != s.charAt(j - k)) {
                        pal = false;
                    }
                }
                if (pal && j - i + 1 > best) {
                    best = j - i + 1;
                }
            }
        }
        System.out.println(best);
    }
}

