class GradeBook {
    private int sum;
    private int count;
    private int highest;

    public GradeBook() {
        sum = 0;
        count = 0;
        highest = 0;
    }

    public void addGrade(int g) {
        sum += g;
        count++;
        if (g > highest) {
            highest = g;
        }
    }

    public int getCount() {
        return count;
    }

    public double getAverage() {
        if (count == 0) {
            return 0.0;
        }
        return (double) sum / count;
    }

    public int getHighest() {
        return highest;
    }
}

